from typing import List, Dict, Optional
from pydantic import BaseModel, Field

class FeatureGeneratorResult(BaseModel):
    """The structured features generated by the Feature Agent."""
    key_features: List[str] = Field(description="Bullet points of outstanding structural features.")
    specifications: Dict[str, str] = Field(description="Technical or structural specifications details.")
    whats_included: List[str] = Field(description="Items included in the kit or course bundle.")
    highlights: List[str] = Field(description="Unique learning highlights.")

class FeatureGeneratorResponse(BaseModel):
    """Structured response wrap returned by the Feature Agent."""
    status: str = Field(description="Result of execution: 'success' or 'failed'.")
    errors: List[str] = Field(default_factory=list, description="List of processing error messages.")
    features: Optional[FeatureGeneratorResult] = Field(default=None, description="The validated generated features.")
